      "surah": 87,
      "ayat": 19,
      "juz": 30,
      "halaman": 592,
      "teks_msi_usmani": "صُحُفِ اِبْرٰهِيْمَ وَمُوْسٰى ࣖ ",
      "teks_gundul": "صحف إبراهيم وموسى",
      "teks": "Ṣuḥufi ibrāhīma wa mūsā.",
      "keterangan": "",
