      "surah": 88,
      "ayat": 26,
      "juz": 30,
      "halaman": 592,
      "teks_msi_usmani": "ثُمَّ اِنَّ عَلَيْنَا حِسَابَهُمْ ࣖ",
      "teks_gundul": "ثم إن علينا حسابهم",
