      "surah": 93,
      "ayat": 11,
      "juz": 30,
      "halaman": 596,
      "teks_msi_usmani": "وَاَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ ࣖ",
      "teks_gundul": "وأما بنعمة ربك فحدث",
      "teks": "Wa ammā bini‘mati rabbika fa ḥaddiṡ.",
      "keterangan": "",
      "terjemah": "Terhadap nikmat Tuhanmu, nyatakanlah (dengan bersyukur).",
      "no_foot": "",
      "teks_foot": ""
